def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx] and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                comps.append(cells)
    counts=[sum(grid[r][c]==9 for r,c in cells) for cells in comps]
    if comps:
        k=counts.index(min(counts))
        for r,c in comps[k]: grid[r][c]=0
    return grid

